question:
Predict the output of the following code involving constructor chaining:

class Base:
    def __init__(self):
        print('Base')

class Child(Base):
    def __init__(self):
        super().__init__()
        print('Child')

class GrandChild(Child):
    def __init__(self):
        print('GrandChild')
        super().__init__()

obj = GrandChild()

answer:
@classmethod
def from_existing(cls, existing_instance):
    return cls(existing_instance.data)
